const body = $json.body || $json;
const opportunity = body.opportunity || body;
const needsApproval = ['VALIDATION_HUMAINE_OBLIGATOIRE', 'BLOQUE'].includes(opportunity.approval_status);
return [{ json: {
  client_id: opportunity.client_id || 'unknown',
  source: opportunity.source || null,
  content_id: opportunity.content_id || null,
  score: opportunity.score || 0,
  approval_status: opportunity.approval_status || 'VALIDATION_HUMAINE_OBLIGATOIRE',
  reviewer_action: needsApproval ? 'review_required' : 'no_review_required',
  draft_message: opportunity.draft_message || '',
  metadata: opportunity
}}];
